    if (!r.finished) return
    setTimer(r.state)
    if (!settingsRef.current.muted) chime()
    if (r.finished.phase === 'focus') {
      const entry: LogEntry = {
        id: String(t) + '-' + Math.random().toString(36).slice(2, 7),
